const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '重心O' },
      { kind: 'text', payload: '支点P' },
      { kind: 'text', payload: '拉力F' }
    ];
  },
  render: function (input, metrics) {
    var sdk = visualSdk;
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var fs = Math.max(10, Math.min(16, Math.round(h * 0.058)));
    var stroke = '#26354a';

    function tw(i, fb) {
      try {
        var m = metrics && metrics[i];
        if (m && typeof m.width === 'number' && m.width > 0) { return m.width; }
      } catch (e) {}
      return fb;
    }

    // 杆：左下端 A 到右上端 B
    var Ax = 0.13 * w, Ay = 0.72 * h;
    var Bx = 0.87 * w, By = 0.40 * h;

    // 重心 O：杆的中点
    var Ox = (Ax + Bx) / 2, Oy = (Ay + By) / 2;

    // 支点 P：杆上靠左的一点，下方三角形支撑
    var tP = 0.32;
    var Px = Ax + (Bx - Ax) * tP;
    var Py = Ay + (By - Ay) * tP;

    var groundY = 0.86 * h;
    var baseHalf = Math.max(fs * 1.3, 0.045 * w);

    // 拉力 F：作用于杆的上端，竖直向上
    var tipY = 0.12 * h;
    var headLen = Math.max(8, h * 0.05);
    var headW = Math.max(5, h * 0.032);
    var dotR = Math.max(2.5, h * 0.012);

    var paths = [
      { id: 'rod', commands: sdk.polyline([[Ax, Ay], [Bx, By]]) },
      { id: 'pivot', commands: sdk.polyline([[Px, Py], [Px - baseHalf, groundY], [Px + baseHalf, groundY], [Px, Py]]) },
      { id: 'force', commands: sdk.polyline([[Bx, By], [Bx, tipY]]) },
      { id: 'forceHead', commands: sdk.polyline([[Bx - headW, tipY + headLen], [Bx, tipY], [Bx + headW, tipY + headLen]]) },
      { id: 'dotO', commands: sdk.circle(Ox, Oy, dotR) },
      { id: 'dotP', commands: sdk.circle(Px, Py, dotR) }
    ];

    var labelO = { type: 'label', text: '重心O', x: Ox + dotR + 5, y: Oy + fs * 1.2, fontSize: fs, fill: stroke, anchor: 'start' };
    var labelP = { type: 'label', text: '支点P', x: Px - baseHalf - 4, y: Py + (groundY - Py) * 0.62 + fs * 0.3, fontSize: fs, fill: stroke, anchor: 'end' };
    var labelF = { type: 'label', text: '拉力F', x: Bx - headW - 6, y: (By + tipY) / 2 + fs * 0.35, fontSize: fs, fill: stroke, anchor: 'end' };

    // 度量仅用于确认标注宽度，避免越界
    tw(0, fs * 3);
    tw(1, fs * 3);
    tw(2, fs * 3);

    return {
      schemaVersion: 1,
      sceneId: 'lever-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'pivot', stroke: stroke, fill: 'none' },
          { type: 'path', pathId: 'rod', stroke: stroke, fill: 'none' },
          { type: 'path', pathId: 'force', stroke: stroke, fill: 'none' },
          { type: 'path', pathId: 'forceHead', stroke: stroke, fill: 'none' },
          { type: 'path', pathId: 'dotO', stroke: stroke, fill: stroke },
          { type: 'path', pathId: 'dotP', stroke: stroke, fill: stroke },
          labelO,
          labelP,
          labelF
        ]
      }
    };
  }
};
